INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'cloudbridge-tech-case-1', 'National Gov-Portal Unified Auth Rollout', 'توحيد نظام الدخول الآمن لبوابة خدمات حكومية', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Seef District with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Seef District وفق أعلى معايير الجودة والالتزام.', 2800, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://cloudbridge.bh/work/cloudbridge-tech-case-1', 'Seef District, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'cloudbridge-tech-2026-outlook', 'CloudBridge 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — كلاود بريدج', 'Key operational benchmarks, real metrics, and 2026 guidance from CloudBridge in Seef District.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من كلاود بريدج في Seef District.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations. Focusing on 24/7 Managed Cloud & SRE Retainer, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة. من خلال خدمة إدارة السحابة والموثوقية 24/7 نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations.</p><p>Focusing on <strong>24/7 Managed Cloud & SRE Retainer</strong>, our Seef District specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة.</p><p>من خلال خدمة <strong>إدارة السحابة والموثوقية 24/7</strong>، يعمل فريقنا في Seef District على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'CloudBridge 2026 GCC Market Outlook & Benchmarks | CloudBridge', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — كلاود بريدج | كلاود بريدج', 'Executive guide by CloudBridge covering 24/7 Managed Cloud & SRE Retainer benchmarks in Bahrain.', 'دليل تنفيذي من كلاود بريدج حول معايير إدارة السحابة والموثوقية 24/7 في البحرين.', 'Insights', '{"it_software","insights","Seef District","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can CloudBridge initiate a 24/7 Managed Cloud & SRE Retainer engagement?', 'كم يستغرق بدء تنفيذ خدمة إدارة السحابة والموثوقية 24/7 لدى كلاود بريدج؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Seef District.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Seef District.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'cloudbridge-tech-case-2', 'Real-Time Treasury FX & SWIFT Gateway', 'بوابة الخزينة الفورية والربط البنكي المؤسسي', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Seef District with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Seef District وفق أعلى معايير الجودة والالتزام.', 2850, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://cloudbridge.bh/work/cloudbridge-tech-case-2', 'Seef District, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'cloudbridge-tech-service-standards', 'Inside Our Cloud SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في إدارة السحابة والموثوقية 24/7', 'Key operational benchmarks, real metrics, and 2026 guidance from CloudBridge in Seef District.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من كلاود بريدج في Seef District.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations. Focusing on Managed SIEM & Vulnerability Audit, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة. من خلال خدمة مراقبة أمنية وفحص الثغرات نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations.</p><p>Focusing on <strong>Managed SIEM & Vulnerability Audit</strong>, our Seef District specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة.</p><p>من خلال خدمة <strong>مراقبة أمنية وفحص الثغرات</strong>، يعمل فريقنا في Seef District على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Cloud SLA: Speed, Quality & Auditability | CloudBridge', 'معايير اتفاقية مستوى الخدمة والجودة في إدارة السحابة والموثوقية 24/7 | كلاود بريدج', 'Executive guide by CloudBridge covering Managed SIEM & Vulnerability Audit benchmarks in Bahrain.', 'دليل تنفيذي من كلاود بريدج حول معايير مراقبة أمنية وفحص الثغرات في البحرين.', 'Operations', '{"it_software","operations","Seef District","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-160440-1 and VAT ID 200016044000002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-160440-1 والرقم الضريبي 200016044000002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-3', 'pcat-cms-3', 'cloudbridge-tech-case-3', 'Multi-Region Retail POS 140-Store Cloud Sync', 'مزامنة سحابية لنقاط بيع 140 متجراً إقليمياً', 'Dilmun Energy Partners', 2025, 'Delivered for Dilmun Energy Partners across Seef District with measurable SLA benchmarks.', 'تم التنفيذ لصالح شركاء دلمون للطاقة في Seef District وفق أعلى معايير الجودة والالتزام.', 2400, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://cloudbridge.bh/work/cloudbridge-tech-case-3', 'Seef District, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-3', 'cloudbridge-tech-arabic-bilingual-ops', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين', 'Key operational benchmarks, real metrics, and 2026 guidance from CloudBridge in Seef District.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من كلاود بريدج في Seef District.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations. Focusing on Cloud-Native Microservices Architecture, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة. من خلال خدمة تصميم معمارية الأنظمة السحابية والخدمات المصغرة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations.</p><p>Focusing on <strong>Cloud-Native Microservices Architecture</strong>, our Seef District specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة.</p><p>من خلال خدمة <strong>تصميم معمارية الأنظمة السحابية والخدمات المصغرة</strong>، يعمل فريقنا في Seef District على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-03.png', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises | CloudBridge', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين | كلاود بريدج', 'Executive guide by CloudBridge covering Cloud-Native Microservices Architecture benchmarks in Bahrain.', 'دليل تنفيذي من كلاود بريدج حول معايير تصميم معمارية الأنظمة السحابية والخدمات المصغرة في البحرين.', 'Governance', '{"it_software","governance","Seef District","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '18 days', true, now() - interval '18 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-3', 'Which corporate payment channels do you support?', 'ما هي قنوات الدفع المؤسسية المتاحة لديكم؟', 'We accept National Bank of Bahrain (NBB) corporate wire/IBAN, BenefitPay, corporate cards, and approved 30-day credit terms.', 'نقبل التحويل البنكي المباشر لحساب National Bank of Bahrain (NBB) وبنفت باي والبطاقات وفترات الائتمان 30 يوماً.', 'payments', true, 3, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
