INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"CloudBridge Systems W.L.L.","nameAr":"كلاود بريدج للأنظمة ذ.م.م","shortEn":"CloudBridge","shortAr":"كلاود بريدج","taglineEn":"Cloud Infrastructure, Enterprise SaaS & Managed Security","taglineAr":"البنية السحابية والأنظمة المؤسسية والأمن السيبراني","aboutEn":"Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations.","aboutAr":"شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة."},"hero":{"titleEn":"CloudBridge — Cloud Infrastructure, Enterprise SaaS & Managed Security","titleAr":"كلاود بريدج — البنية السحابية والأنظمة المؤسسية والأمن السيبراني","ctaLabelEn":"Explore CloudBridge","ctaLabelAr":"استكشف كلاود بريدج"},"featuredServices":[{"code":"SVC-MSP","en":"24/7 Managed Cloud & SRE Retainer","ar":"إدارة السحابة والموثوقية 24/7","rate":1400},{"code":"SVC-SOC","en":"Managed SIEM & Vulnerability Audit","ar":"مراقبة أمنية وفحص الثغرات","rate":950},{"code":"ITS-ARCH","en":"Cloud-Native Microservices Architecture","ar":"تصميم معمارية الأنظمة السحابية والخدمات المصغرة","rate":2400},{"code":"ITS-APP","en":"Next.js & Go Full-Stack Platform Build","ar":"تطوير المنصات الرقمية الكاملة Next.js و Go","rate":2800}]}'::jsonb, '{"company":{"nameEn":"CloudBridge Systems W.L.L.","nameAr":"كلاود بريدج للأنظمة ذ.م.م","shortEn":"CloudBridge","shortAr":"كلاود بريدج","taglineEn":"Cloud Infrastructure, Enterprise SaaS & Managed Security","taglineAr":"البنية السحابية والأنظمة المؤسسية والأمن السيبراني","aboutEn":"Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations.","aboutAr":"شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة."},"hero":{"titleEn":"CloudBridge — Cloud Infrastructure, Enterprise SaaS & Managed Security","titleAr":"كلا