INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('7d25d4e1-dbdf-4761-a86c-01c076c1780c', 'Eng. Salman Al-Moayyed', 'م. سلمان المؤيد', 'Almoayyed Contracting Group W.L.L.', 'مجموعة المؤيد للمقاولات ذ.م.م', 'CloudBridge consistently delivers on complex Bahrain commercial schedules with transparent VAT documentation and responsive bilingual account leads.', 'تلتزم كلاود بريدج دائماً بالجداول الزمنية للمشاريع التجارية في البحرين مع توثيق ضريبي شفاف وفريق حسابات سريع الاستجابة.', 5, true, 20, 2026, now() - interval '15 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('ab50622b-a759-42a6-aae6-9f8e21495566', 'Dr. Hessa Al-Zayani', 'د. حصة الزياني', 'Dilmunia Health & Wellness Center', 'مركز دلمونيا للصحة والعافية', 'From initial quotation to final commissioning, the CloudBridge operations team exceeded our SLA expectations.', 'من عرض السعر الأولي حتى التسليم النهائي، تجاوز فريق عمليات كلاود بريدج توقعاتنا في الالتزام بمستوى الخدمة.', 5, true, 21, 2026, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('26d77a41-63fc-4a20-a0a9-0e57c6b4aed3', 'Are all CloudBridge invoices compliant with Bahrain NBR 10% VAT regulations?', 'هل جميع فواتير كلاود بريدج متوافقة مع لوائح ضريبة القيمة المضافة 10% في البحرين؟', 'Yes. Every quotation and tax invoice includes our registered VAT ID (200016044000002), itemized tax calculations, and verifiable QR metadata.', 'نعم، تتضمن كل فاتورة ضريبية وعرض سعر رقمنا الضريبي المسجل (200016044000002) مع تفصيل الضريبة ورمز التحقق.', 'billing', true, 20, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('764bf78e-3f6d-4ee4-a5da-978ee6932bda', 'Which Bahrain governorates and GCC destinations do you cover?', 'ما هي المحافظات في البحرين ووجهات الخليج التي تغطونها؟', 'We provide same-day and next-day fulfillment across Capital, Muharraq, Northern, and Southern Governorates, plus scheduled cross-border freight to Saudi Arabia, UAE, Qatar, Kuwait, and Oman.', 'نوفر التوصيل في نفس اليوم أو اليوم التالي في جميع محافظات البحرين، بالإضافة إلى الشحن المجدول لدول مجلس التعاون الخليجي.', 'logistics', true, 21, now() - interval '23 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.page (id, slug, page_type, title_en, title_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, blocks, is_visible, in_header, in_footer, sort_order, created_at, updated_at) VALUES ('pg-home', 'home', 'home', 'CloudBridge', 'كلاود بريدج', 'CloudBridge | Cloud Infrastructure, Enterprise SaaS & Managed Security', 'كلاود بريدج | البنية السحابية والأنظمة المؤسسية والأمن السيبراني', 'Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations. Explore CloudBridge in Seef District.', 'شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة. تصفح صفحة كلاود بريدج.', '[{"id":"pg-home-hero","type":"hero","titleEn":"CloudBridge | Cloud Infrastructure, Enterprise SaaS & Managed Security","titleAr":"كلاود بريدج | البنية السحابية والأنظمة المؤسسية والأمن السيبراني","image":"/api/files/media/banners/banner-01.png"},{"id":"pg-home-body","type":"rich_section","ctaEn":"Request Proposal","ctaAr":"طلب عرض سعر","sortOrder":1}]'::jsonb, true, true, false, 1, now() - interval '2160 hours', now()) ON CONFLICT (id) DO NOTHING;
